// Assemble the Numa Shared home page.
//   node scripts/build-home.mjs          -> convex/lib/homePage.generated.ts
//   node scripts/build-home.mjs --check  -> fails if the generated file is stale
// Sources: web-home/page.html, home.css, home.js, assets/*
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const src = (...p) => path.join(here, "..", "web-home", ...p);
const hash = (buf) => crypto.createHash("sha256").update(buf).digest("hex").slice(0, 10);
const rd = (f) => fs.readFileSync(f);

const assets = {
  "app-home.webp": { file: src("assets", "app-09-home.webp"), type: "image/webp" },
  "app-expense.webp": { file: src("assets", "app-22-expense.webp"), type: "image/webp" },
  "bricolage-700.woff2": { file: src("assets", "bricolage-700.woff2"), type: "font/woff2" },
};
const js = rd(src("home.js"));
const v = {
  JS_VERSION: hash(js),
  IMG_VERSION: hash(Buffer.concat([rd(assets["app-home.webp"].file), rd(assets["app-expense.webp"].file)])),
  FONT_VERSION: hash(rd(assets["bricolage-700.woff2"].file)),
};
let css = rd(src("home.css")).toString("utf8").replace(/\{\{(\w+)\}\}/g, (_, k) => v[k] ?? `{{${k}}}`);
css = css.replace(/\/\*[\s\S]*?\*\//g, "").replace(/\n{2,}/g, "\n").trim();
let html = rd(src("page.html")).toString("utf8").replace("{{CSS}}", () => css).replace(/\{\{(JS_VERSION|IMG_VERSION)\}\}/g, (_, k) => v[k]);

if (/\u2014/.test(html) || /\u2014/.test(css)) throw new Error("em dash in page source");

const outFile = path.join(here, "..", "convex", "lib", "homePage.generated.ts");
const check = process.argv.includes("--check");
const lines = [
  "// GENERATED by scripts/build-home.mjs from web-home/. Do not edit by hand.",
  "// Run `npm run build:home` after changing anything in web-home/.",
  "",
  `export const homeTemplate = ${JSON.stringify(html)};`,
  `export const homeScript = ${JSON.stringify(js.toString("utf8"))};`,
  "export const homeAssets: Readonly<Record<string, { type: string; base64: string }>> = {",
  ...Object.entries(assets).map(([n, a]) => `  ${JSON.stringify(n)}: { type: ${JSON.stringify(a.type)}, base64: ${JSON.stringify(rd(a.file).toString("base64"))} },`),
  "};",
  "",
].join("\n");
if (check) {
  if (!fs.existsSync(outFile) || fs.readFileSync(outFile, "utf8") !== lines) {
    console.error("convex/lib/homePage.generated.ts is stale. Run: npm run build:home");
    process.exit(1);
  }
  console.log("homePage.generated.ts is up to date");
} else {
  fs.writeFileSync(outFile, lines);
  console.log("wrote", path.relative(process.cwd(), outFile), v);
}
